    int kde_output_device_mode_v2::deferred_destroy_global_func(void *data) {
        auto object = static_cast<kde_output_device_mode_v2 *>(data);
        wl_global_destroy(object->m_global);
        object->m_global = nullptr;
        wl_event_source_remove(object->m_globalRemovedEvent);
        object->m_globalRemovedEvent = nullptr;
        wl_list_remove(&object->m_displayDestroyedListener.link);
        object->kde_output_device_mode_v2_destroy_global();
        return 0;
    }

    kde_output_device_mode_v2::kde_output_device_mode_v2(struct ::wl_client *client, int id, int version)
        : m_resource_map()
        , m_resource(nullptr)
        , m_global(nullptr)
        , m_display(nullptr)
        , m_globalRemovedEvent(nullptr)
    {
        init(client, id, version);
    }

    kde_output_device_mode_v2::kde_output_device_mode_v2(struct ::wl_display *display, int version)
        : m_resource_map()
        , m_resource(nullptr)
        , m_global(nullptr)
        , m_display(nullptr)
        , m_globalRemovedEvent(nullptr)
    {
        init(display, version);
    }

    kde_output_device_mode_v2::kde_output_device_mode_v2(struct ::wl_resource *resource)
        : m_resource_map()
        , m_resource(nullptr)
        , m_global(nullptr)
        , m_display(nullptr)
        , m_globalRemovedEvent(nullptr)
    {
        init(resource);
    }

    kde_output_device_mode_v2::kde_output_device_mode_v2()
        : m_resource_map()
        , m_resource(nullptr)
        , m_global(nullptr)
        , m_display(nullptr)
        , m_globalRemovedEvent(nullptr)
    {
    }

    kde_output_device_mode_v2::~kde_output_device_mode_v2()
    {
        for (auto resource : std::as_const(m_resource_map))
            resource->kde_output_device_mode_v2_object = nullptr;

        if (m_resource)
            m_resource->kde_output_device_mode_v2_object = nullptr;

        if (m_global) {
            if (m_globalRemovedEvent)
                wl_event_source_remove(m_globalRemovedEvent);
            wl_global_destroy(m_global);
            wl_list_remove(&m_displayDestroyedListener.link);
        }
    }

    void kde_output_device_mode_v2::init(struct ::wl_client *client, int id, int version)
    {
        m_resource = bind(client, id, version);
    }

    void kde_output_device_mode_v2::init(struct ::wl_resource *resource)
    {
        m_resource = bind(resource);
    }

    kde_output_device_mode_v2::Resource *kde_output_device_mode_v2::add(struct ::wl_client *client, int version)
    {
        Resource *resource = bind(client, 0, version);
        m_resource_map.insert(client, resource);
        return resource;
    }

    kde_output_device_mode_v2::Resource *kde_output_device_mode_v2::add(struct ::wl_client *client, int id, int version)
    {
        Resource *resource = bind(client, id, version);
        m_resource_map.insert(client, resource);
        return resource;
    }

    kde_output_device_mode_v2::Resource *kde_output_device_mode_v2::add(struct ::wl_resource *resource)
    {
        return *m_resource_map.insert(wl_resource_get_client(resource), bind(resource));
    }

    void kde_output_device_mode_v2::init(struct ::wl_display *display, int version)
    {
        m_display = display;
        m_global = wl_global_create(display, &::kde_output_device_mode_v2_interface, version, this, bind_func);
        m_displayDestroyedListener.notify = kde_output_device_mode_v2::display_destroy_func;
        m_displayDestroyedListener.parent = this;
#ifdef HAVE_ACK_GLOBAL_REMOVE
        wl_global_set_withdrawn_listener(m_global, [](wl_global *global) {
            auto object = static_cast<kde_output_device_mode_v2 *>(wl_global_get_user_data(global));
            object->kde_output_device_mode_v2_destroy_global();
        });
#endif
        wl_display_add_destroy_listener(display, &m_displayDestroyedListener);
    }

